// Configuration
const width = 800;
const height = 800;
const margin = { top: 20, right: 150, bottom: 20, left: 20 };

// Color scale for sectors
const sectorColors = {
    'Information Technology': '#3b82f6',
    'Industry': '#10b981',
    'Energy': '#f59e0b',
    'Financial': '#8b5cf6',
    'ETF': '#6b7280'
};

let stockData = [];
let selectedTicker = null;

// Create SVG
const svg = d3.select('#bubble-chart')
    .append('svg')
    .attr('width', width + margin.left + margin.right)
    .attr('height', height + margin.top + margin.bottom);

const g = svg.append('g')
    .attr('transform', `translate(${margin.left},${margin.top})`);

// Create tooltip
const tooltip = d3.select('body')
    .append('div')
    .attr('class', 'tooltip');

// Load and process data
d3.csv('data/stock-descriptions.csv').then(data => {
    // Process data
    stockData = data.map(d => ({
        ticker: d.ticker,
        name: d['full name'],
        sector: d.sector,
        marketCap: d.marketCap ? parseFloat(d.marketCap) : null,
        isETF: d.sector === 'ETF'
    }));

    // Create bubble chart
    createBubbleChart();

    // Create table
    createTable();
});

function createBubbleChart() {
    // Calculate bubble sizes
    const marketCaps = stockData.filter(d => d.marketCap).map(d => d.marketCap);
    const minCap = d3.min(marketCaps);
    const maxCap = d3.max(marketCaps);

    // Size scale for bubbles
    const radiusScale = d3.scaleSqrt()
        .domain([minCap, maxCap])
        .range([15, 60]);

    // ETF size
    const etfRadius = 20;

    // Add radius to data
    stockData.forEach(d => {
        d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
    });

    // Get unique sectors
    const sectors = [...new Set(stockData.map(d => d.sector))];

    // Calculate sector positions (clusters)
    const sectorPositions = {};
    const numSectors = sectors.length;
    const angleStep = (2 * Math.PI) / numSectors;
    const centerX = width / 2;
    const centerY = height / 2;
    const clusterRadius = Math.min(width, height) * 0.25;

    sectors.forEach((sector, i) => {
        const angle = i * angleStep;
        sectorPositions[sector] = {
            x: centerX + Math.cos(angle) * clusterRadius,
            y: centerY + Math.sin(angle) * clusterRadius
        };
    });

    // Create force simulation
    const simulation = d3.forceSimulation(stockData)
        .force('x', d3.forceX(d => sectorPositions[d.sector].x).strength(0.1))
        .force('y', d3.forceY(d => sectorPositions[d.sector].y).strength(0.1))
        .force('collide', d3.forceCollide(d => d.radius + 2))
        .force('charge', d3.forceManyBody().strength(-5))
        .force('center', d3.forceCenter(width / 2, height / 2).strength(0.05));

    // Create bubbles
    const bubbles = g.selectAll('.bubble')
        .data(stockData)
        .enter()
        .append('g')
        .attr('class', 'bubble-group');

    bubbles.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector])
        .on('mouseover', function(event, d) {
            if (!d.isETF) {
                tooltip
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px')
                    .html(`
                        <strong>${d.ticker}</strong><br/>
                        ${d.name}<br/>
                        Sector: ${d.sector}
                    `)
                    .classed('show', true);
            }
        })
        .on('mouseout', function() {
            tooltip.classed('show', false);
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    bubbles.append('text')
        .attr('class', 'bubble-label')
        .attr('dy', '0.35em')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius * 0.6, 14) + 'px');

    // Update positions on tick
    simulation.on('tick', () => {
        bubbles.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    // Create legend
    const legend = svg.append('g')
        .attr('class', 'legend')
        .attr('transform', `translate(${width + margin.left + 10}, ${margin.top})`);

    sectors.forEach((sector, i) => {
        const legendItem = legend.append('g')
            .attr('class', 'legend-item')
            .attr('transform', `translate(0, ${i * 25})`);

        legendItem.append('rect')
            .attr('class', 'legend-color')
            .attr('width', 18)
            .attr('height', 18)
            .attr('fill', sectorColors[sector]);

        legendItem.append('text')
            .attr('x', 24)
            .attr('y', 9)
            .attr('dy', '0.35em')
            .text(sector)
            .style('font-size', '12px');
    });
}

function createTable() {
    const tableContainer = d3.select('#table-container');

    const table = tableContainer.append('table');
    const thead = table.append('thead');
    const tbody = table.append('tbody');

    // Create header
    thead.append('tr')
        .selectAll('th')
        .data(['Ticker', 'Company Name', 'Sector', 'Market Cap'])
        .enter()
        .append('th')
        .text(d => d);

    // Create rows
    const rows = tbody.selectAll('tr')
        .data(stockData)
        .enter()
        .append('tr')
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Ticker cell
    rows.append('td')
        .attr('class', 'ticker-cell')
        .text(d => d.ticker);

    // Company name cell
    rows.append('td')
        .text(d => d.name);

    // Sector cell
    rows.append('td')
        .text(d => d.sector);

    // Market cap cell
    rows.append('td')
        .text(d => {
            if (!d.marketCap) return 'N/A';

            const cap = d.marketCap;
            if (cap >= 1e12) {
                return (cap / 1e12).toFixed(2) + 'T';
            } else if (cap >= 1e9) {
                return (cap / 1e9).toFixed(2) + 'B';
            } else if (cap >= 1e6) {
                return (cap / 1e6).toFixed(2) + 'M';
            }
            return cap.toFixed(2);
        });
}

function selectStock(ticker) {
    // Update selected ticker
    selectedTicker = ticker === selectedTicker ? null : ticker;

    // Update bubble chart
    d3.selectAll('.bubble')
        .style('opacity', d => {
            if (!selectedTicker) return 1;
            return d.ticker === selectedTicker ? 1 : 0.3;
        })
        .attr('stroke', d => d.ticker === selectedTicker ? '#333' : 'none')
        .attr('stroke-width', d => d.ticker === selectedTicker ? 3 : 0);

    // Update table
    d3.selectAll('tbody tr')
        .classed('highlighted', d => d.ticker === selectedTicker);

    // Scroll to highlighted row if selected
    if (selectedTicker) {
        const highlightedRow = d3.select('tbody tr.highlighted').node();
        if (highlightedRow) {
            highlightedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    }
}

